{
  "name": "pairwise_preference_loss",
  "intuition": "This loss encourages the model to assign higher log probabilities to preferred options based on the cost_gap signal, effectively training it to prefer lower-cost outputs. Using logsigmoid transforms the difference in log_probs into a smooth preference score, scaled by a weight that emphasizes importance of the pairwise comparison. The approach aligns with the lower_is_better objective by penalizing cases where the non-preferred option has a higher probability, promoting preference consistency.",
  "pseudocode": "loss = mean( logsigmoid( weight * (log_prob_l - log_prob_w) ) )",
  "hyperparams": {
    "paradigm_family": "preference",
    "signal_family": "cost-based",
    "link_family": "logistic",
    "agg_family": "pairwise",
    "constraint_family": "probabilistic",
    "other_hparams": "none"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch.get('cost_gap', None)\n    # Compute the preference score: higher if log_prob_l > log_prob_w when cost_gap indicates preference\n    score_diff = mul(weight, sub(log_prob_l, log_prob_w))\n    loss_values = logsigmoid(score_diff)\n    return mean(loss_values)"
}

{
  "name": "loss_tanh_advantage_weighted_score_diff",
  "intuition": "Removed unsupported 'rank_gap' signal to comply with expects constraints. Simplified to use advantage_gap as a weight on the tanh of the score difference. This stabilizes by avoiding unstable normalization on rank_gap and enforces smooth preference via tanh(score_diff) weighted by advantage_gap and batch weight.",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_gap"
    ]
  },
  "generated_loss": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    advantage_gap = batch['advantage_gap']\n    score_diff = ops.sub(lpw, lpl)\n    tanh_score_diff = ops.tanh(score_diff)\n    loss_per_pair = ops.mul(ops.sub(ops.ones_like(tanh_score_diff), tanh_score_diff), advantage_gap)\n    if weight is not None:\n        loss_per_pair = ops.mul(loss_per_pair, weight)\n    return ops.mean(loss_per_pair)"
}

{
  "name": "loss_tanh_advantage_weighted_score",
  "intuition": "Removed the unsupported 'rank_gap' key from expects and loss computation. Simplify by directly using the advantage_gap weighted score difference between winning and losing log-probs passed through a tanh link, clamped for numerical stability and weighted appropriately. This avoids numerical instability and ensures only allowed keys are used.",
  "generated_loss": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    advantage_gap = batch['advantage_gap']\n    score_diff = ops.sub(lpw, lpl)\n    weighted_score = ops.mul(advantage_gap, score_diff)\n    # Clamp weighted_score to [-10,10] to stabilize tanh\n    weighted_score_clamped = ops.clamp(weighted_score, -10.0, 10.0)\n    loss_per_pair = ops.sub(ops.ones_like(weighted_score_clamped), ops.tanh(weighted_score_clamped))\n    if weight is not None:\n        loss_per_pair = ops.mul(loss_per_pair, weight)\n    return ops.mean(loss_per_pair)",
  "implementation_hint": {
    "mode": "pairwise",
    "expects": [
      "log_prob_w",
      "log_prob_l",
      "weight",
      "advantage_gap"
    ]
  }
}

{
  "name": "loss_pairwise_rankgap_tanh_advantage",
  "intuition": "Shift from margin-based pairwise losses to a rank-based loss using tanh link that exploits advantage signals to provide a smooth ranking penalty.",
  "pseudocode": "rank_diff = delta_rank\nadv_diff = advantage_w - advantage_l\npenalty = tanh(scale * adv_diff * rank_diff)\nloss = mean(weight * penalty)",
  "hyperparams": {
    "paradigm_family": "pairwise_ranking",
    "signal_family": "advantage_gap",
    "link_family": "tanh",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["tanh", "mean", "mul", "sub"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "delta_rank"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    rank_diff = batch['delta_rank']\n    scale = float(extra.get('hyperparams', {}).get('scale', 1.0))\n    adv_diff = ops.sub(adv_w, adv_l)\n    penalty = ops.tanh(ops.mul(ops.mul(scale, adv_diff), rank_diff))\n    if weight is not None:\n        penalty = ops.mul(penalty, weight)\n    return ops.mean(penalty)"
}

{
  "name": "pairwise_cost_gap_preference_loss",
  "intuition": "This loss encourages the model to rank sequence pairs by their cost gap, promoting preferences for lower cost sequences. By applying a sigmoid on the negative cost gap and weighting pairwise comparisons, it emphasizes differences where the advantage is most significant, aligning training with the objective of minimizing costs.",
  "pseudocode": "loss = mean over pairs of sigmoid(-cost_gap) * weight * indicator(preferred sequence has lower cost)",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "pairwise",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "cost_difference",
    "other_hparams": "none"
  },
  "operators_used": ["logsigmoid", "mul", "mean", "abs", "clamp"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    cost_gap = batch.get('cost_gap', None)\n    if cost_gap is None:\n        cost_gap = batch.get('cost_gap', ops.zeros_like(log_prob_w))\n    # Compute pairwise preference\n    # Sigmoid of negative cost gap emphasizes preferences for lower cost\n    pref_signal = ops.logsigmoid(ops.neg(cost_gap))\n    # Combine with weight\n    weighted_pref = pref_signal * weight\n    # Return mean as scalar loss\n    loss = ops.mean(weighted_pref)\n    return loss"
}

{
  "name": "pairwise_cost_gap_margin_loss",
  "intuition": "This loss encourages the model to rank higher-cost outputs with a larger margin, promoting preference for lower costs with a significant separation. It uses the cost_gap signal to quantify the difference and enforces that preferred samples have a strictly better (lower) cost, boosting the model's ability to distinguish high vs. low quality choices effectively.",
  "pseudocode": "loss = mean(max(0, margin - (cost_w - cost_l)))",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "cost_gap",
    "link_family": "margin",
    "agg_family": "pairwise",
    "constraint_family": "nonneg",
    "other_hparams": "margin=1.0"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    margin = extra.get('margin', 1.0)\n    cost_w = batch['cost_w']\n    cost_l = batch['cost_l']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch.get('weight', ops.ones_like(log_prob_w))\n    cost_gap = batch['cost_gap']\n    # Compute pairwise difference\n    diff = cost_w - cost_l\n    # Loss encourages difference to be greater than margin\n    loss = ops.maximum(0.0, margin - diff)\n    # Weight the loss\n    weighted_loss = loss * weight\n    return ops.mean(weighted_loss)"
}

