{
  "name": "loss_softplus_advantagegap_grad_safe",
  "intuition": "Ensure advantage gap is computed from batch tensors with requires_grad via differentiable ops, preserving softplus penalty on scaled advantage.",
  "pseudocode": "adv_gap = advantage_w - advantage_l  # differentiable\nscaled = clamp(alpha * adv_gap, -10, 10)\nloss = mean(weight * softplus(-scaled))",
  "hyperparams": {
    "paradigm_family": "pairwise_advantage_regression",
    "signal_family": "advantage_gap",
    "link_family": "softplus",
    "agg_family": "mean",
    "constraint_family": "clamp_stabilized"
  },
  "operators_used": ["softplus", "clamp", "mul", "sub", "mean", "neg"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    adv_w = batch['advantage_w']\n    adv_l = batch['advantage_l']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    # recompute adv_gap using differentiable ops to ensure grad_fn\n    adv_gap = ops.sub(adv_w, adv_l)\n    scaled = ops.clamp(ops.mul(alpha, adv_gap), -10.0, 10.0)\n    loss_raw = ops.softplus(ops.neg(scaled))\n    loss_weighted = ops.mul(loss_raw, weight)\n    return ops.mean(loss_weighted)"
}

