{
  "name": "rank_gap_sigmoid_advantage_fixed_v4",
  "intuition": "Preserve sigmoid-based smooth ranking loss using advantage signals; ensure gradients flow by using weight as is without cloning requires_grad forcing.",
  "pseudocode": "adv_diff = advantage_w - advantage_l\nscaled = alpha * adv_diff\nsig = sigmoid(scaled)\nloss = mean(weight * (1 - sig))",
  "hyperparams": {
    "paradigm_family": "pairwise_rank_gap",
    "signal_family": "advantage_gap",
    "link_family": "sigmoid",
    "agg_family": "mean",
    "constraint_family": "none"
  },
  "operators_used": ["sigmoid", "sub", "mul", "mean", "ones_like"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n\n    weight = batch['weight'] if 'weight' in batch else ops.ones_like(lpw)\n\n    adv_diff = ops.sub(advantage_w, advantage_l)\n    scaled = ops.mul(alpha, adv_diff)\n    sig = ops.sigmoid(scaled)\n    loss = ops.mul(weight, ops.sub(ops.ones_like(sig), sig))\n    return ops.mean(loss)"
